package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.os.*;import android.widget.*;import java.util.*;

public final class CollectionEditorActivity extends WorkspaceActivity {
    boolean restoring;String hash,search="";int page;EditText topic,series,newName,query;LinearLayout entries;final Map<Long,Boolean> changed=new LinkedHashMap<>();
    String title(){return "Organizar livro";}
    void load(){if(topic==null){hash=getIntent().getStringExtra("hash");if(hash==null||!hash.matches("[a-f0-9]{64}")){finish();return;}topic=PlusUi.input(this,"Assunto","",120);series=PlusUi.input(this,"Série","",120);newName=PlusUi.input(this,"Nova colecção (opcional)","",100);content.addView(topic);content.addView(series);content.addView(newName);query=PlusUi.input(this,"Pesquisar colecções","",100);content.addView(query);action("Pesquisar",()->{search=query.getText().toString().trim();page=0;load();});entries=PlusUi.column(this);content.addView(entries);action("Guardar",this::save);PlusUi.run(this,()->{try(PlusStore db=new PlusStore(this)){List<StudyStore.Row> meta=db.rows("book_meta","hash=?",new String[]{hash},null,1);if(!restoring&&!meta.isEmpty())PlusUi.post(this,()->{topic.setText(meta.get(0).s("topic"));series.setText(meta.get(0).s("series"));});}});}
        final String q=search;final int offset=page*40;PlusUi.run(this,()->{List<StudyStore.Row> rows;Set<Long> members=new HashSet<>();long total;try(PlusStore db=new PlusStore(this)){String clause="name LIKE ? ESCAPE '\\'";String[] args={StudySchedule.like(q)};try(Cursor count=db.getReadableDatabase().query("collections",new String[]{"COUNT(*)"},clause,args,null,null,null)){count.moveToFirst();total=count.getLong(0);}rows=new ArrayList<>();try(Cursor c=db.getReadableDatabase().rawQuery("SELECT c.id,c.name,EXISTS(SELECT 1 FROM book_collections b WHERE b.collection=c.id AND b.hash=?) AS member FROM collections c WHERE "+clause+" ORDER BY name COLLATE NOCASE,id LIMIT 40 OFFSET ?",new String[]{hash,args[0],""+offset})){while(c.moveToNext()){rows.add(TaskStore.row(c));if(c.getInt(2)!=0)members.add(c.getLong(0));}}}PlusUi.post(this,()->{entries.removeAllViews();entries.addView(label((offset+1)+"–"+Math.min(total,offset+rows.size())+" / "+total,12));for(StudyStore.Row r:rows){CheckBox box=new CheckBox(this);box.setText(r.s("name"));box.setTextColor(colors.ink);box.setMinHeight(dp(48));box.setChecked(changed.containsKey(r.id())?changed.get(r.id()):members.contains(r.id()));box.setOnCheckedChangeListener((button,on)->changed.put(r.id(),on));entries.addView(box);}LinearLayout nav=new LinearLayout(this);if(page>0){TextView b=label("Anterior",14);UiBox.style(b);b.setOnClickListener(v->{page--;load();});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}if(offset+rows.size()<total){TextView b=label("Seguinte",14);UiBox.style(b);b.setOnClickListener(v->{page++;load();});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}entries.addView(nav);});});}
    void save(){final String t=topic.getText().toString().trim(),s=series.getText().toString().trim(),n=newName.getText().toString().trim();Map<Long,Boolean> delta=new LinkedHashMap<>(changed);PlusUi.run(this,()->{BookCategories.saveChanges(this,hash,t,s,n,delta);StudyEvents.changed();PlusUi.post(this,()->{PlusUi.toast(this,"Livro organizado.");finish();});});}
    public void onCreate(Bundle state){restoring=state!=null;super.onCreate(state);if(state!=null){topic.setText(state.getString("topic",""));series.setText(state.getString("series",""));newName.setText(state.getString("new",""));String[] keys=state.getStringArray("collections");if(keys!=null)for(String key:keys){String[] bits=key.split(":");changed.put(Long.parseLong(bits[0]),bits[1].equals("1"));}}}
    protected void onSaveInstanceState(Bundle out){out.putString("topic",topic.getText().toString());out.putString("series",series.getText().toString());out.putString("new",newName.getText().toString());List<String> keys=new ArrayList<>();for(Map.Entry<Long,Boolean> e:changed.entrySet())keys.add(e.getKey()+":"+(e.getValue()?1:0));out.putStringArray("collections",keys.toArray(new String[0]));super.onSaveInstanceState(out);}
}
